import{_ as o,c,o as t,ae as a}from"./chunks/framework.CFeneB-q.js";const u=JSON.parse('{"title":"移动端 · 提交规范","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/standards/commit-specification.md","filePath":"mobile/standards/commit-specification.md","lastUpdated":1789438865000}'),s={name:"mobile/standards/commit-specification.md"};function d(i,e,n,r,l,p){return t(),c("div",null,[...e[0]||(e[0]=[a(`<h1 id="移动端-·-提交规范" tabindex="-1">移动端 · 提交规范 <a class="header-anchor" href="#移动端-·-提交规范" aria-label="Permalink to &quot;移动端 · 提交规范&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">强制设施缺失（如实记录）</p><p>模板工程当前<strong>无 husky / commitlint / eslint 门禁</strong>，本规范靠自觉 + MR 评审保证。给模板工程补齐与 PC 端同配置的提交设施已列入遗留项（缺口分析 §2.1），补齐后随模板派生自然铺开。</p></div><h2 id="commit-message-格式-对齐-pc-端" tabindex="-1">commit message 格式（对齐 PC 端） <a class="header-anchor" href="#commit-message-格式-对齐-pc-端" aria-label="Permalink to &quot;commit message 格式（对齐 PC 端）&quot;">​</a></h2><p>格式：<code>&lt;type&gt;(&lt;scope&gt;): &lt;subject&gt;</code></p><ul><li><strong>type</strong> 枚举与 PC 端 commitlint 配置一致： <code>feature</code> / <code>bug</code> / <code>fix</code> / <code>ui</code> / <code>docs</code> / <code>style</code> / <code>perf</code> / <code>refactor</code> / <code>release</code> / <code>deploy</code> / <code>test</code> / <code>chore</code> / <code>revert</code> / <code>build</code> / <code>merge</code></li><li><strong>scope</strong>：必填，写模块或业务域，如 <code>qual_mgmt</code>、<code>request</code>、<code>login</code>、<code>manifest</code>；</li><li><strong>subject</strong>：≤72 字符，中文简述，不加句号。</li></ul><p>示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feature(qual_mgmt): 新增水泥拌合站实时动态页面</span></span>
<span class="line"><span>bug(personnel_mgmt): 修复打卡记录分页数据重复</span></span>
<span class="line"><span>fix(request): 兼容 cl 客户前缀改写后 token 失效场景</span></span>
<span class="line"><span>chore(manifest): 版本升级 2.4.3 / versionCode 20403</span></span></code></pre></div><h2 id="分支命名" tabindex="-1">分支命名 <a class="header-anchor" href="#分支命名" aria-label="Permalink to &quot;分支命名&quot;">​</a></h2><p>同 PC 端（<a href="/E9-Front-Dev-Guide.io/pc/standards/commit-specification.html">查看 PC 端提交规范</a>）：<code>master</code> / <code>stable</code> 锁定；常规开发 <code>dev/功能名称</code>；修复 <code>fix/</code>、<code>hotfix/</code>、<code>feat/</code>、<code>refactor/</code>、<code>perf/</code>。</p><p>移动端补充约定：发版分支建议带版本号（如 <code>release/2.4.3</code>），便于与安装包归档（<code>keystone_public/安装包</code>）对应。</p><h2 id="版本发布纪律" tabindex="-1">版本发布纪律 <a class="header-anchor" href="#版本发布纪律" aria-label="Permalink to &quot;版本发布纪律&quot;">​</a></h2><p>App / 小程序发版（<code>manifest.json</code> 的 <code>versionName</code> / <code>versionCode</code> 升级）必须独立提交，type 用 <code>chore(manifest)</code>，保持「提交 ↔ 安装包」可追溯。</p><hr><p><strong>负责人</strong>：E9 前端团队 ｜ <strong>最后验证日期</strong>：2026-09-16 ｜ <strong>对应蓝本项目</strong>：<code>delivery-template-uniapp</code></p>`,14)])])}const h=o(s,[["render",d]]);export{u as __pageData,h as default};
